// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract ERC721ReceiverForwarder {
    function forwardOnERC721Received(
        address target,
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) external returns (bytes4) {
        (bool success, bytes memory ret) = target.call(
            abi.encodeWithSignature("onERC721Received(address,address,uint256,bytes)", operator, from, tokenId, data)
        );
        require(success, "forward failed");
        return abi.decode(ret, (bytes4));
    }
}

contract InvMutTest is Test {
    PrivatePool c;
    ERC721ReceiverForwarder forwarder;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
        forwarder = new ERC721ReceiverForwarder();
    }

    function testFuzz_property(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) public {
        bytes4 returned = forwarder.forwardOnERC721Received(address(c), operator, from, tokenId, data);
        assertTrue(returned == 0x150b7a02);
    }
}
